    "content": {
      "title": "Run The Compass On This Decision",
      "instruction": "Read the case, then choose the better-reasoned move.",
      "question": "Given the two offers, what's the compass-consistent way to decide, rather than defaulting to the higher-paying one automatically?",
      "cases": [
        {
          "id": "case1",
          "name": "The two offers",
          "text": "One higher-paying and expected by others; one lower-paying but connected to a long-named value.",
          "label": "The Case"
        }
      ],
      "options": [
        {
          "id": "compass",
          "label": "Name the value under each option, check the motivation source for each, then run self-concordance before deciding"
        },
        {
          "id": "default",
          "label": "Take the higher-paying offer — it's the objectively better choice"
        }
      ],
      "feedbackMap": {
        "compass": {
          "title": "Right",
          "body": "Running the full compass — value, motivation source, self-concordance — is what the whole section builds toward; it doesn't guarantee one answer, but it makes the decision an informed one instead of a default.",
          "chain": [
            "A practical decision is exactly the domain the compass was built for.",
            "Running it produces an informed choice, not an automatic one."
          ]
        },
        "default": {
          "title": "Not quite",
          "body": "Defaulting to the higher pay skips the whole compass this section taught — the point isn't that money is wrong, it's that the decision should be checked, not defaulted.",
          "chain": [
            "Skipping the value/motivation/concordance check is exactly what this section teaches against."
          ],
          "counterTitle": "Try the compass angle",
          "counterBody": "Ask what running values_vs_goals, motivation type, and self-concordance on both options would actually reveal."
        }
      }
    }
