            }
          ]
        }
      ],
      "joinStrategy": {
        "type": "template",
        "template": "{check} — {so}."
      },
      "comparisonFeedback": "A practical decision is exactly what the compass is for; a weeks-long low mood is a different kind of signal, and routing it elsewhere is the honest, safer response."
